export const scoreArmy = (army: Card[]): number => {
  const types = distinctTypes(army);
  if (!types.has(SPHINX)) return NO_SPHINX_SCORE;

  const otherTypes = types.size - 1;
  if (otherTypes <= FREE_TYPES) return SCORE_WITHIN_FREE_TYPES;

  const extraTypes = otherTypes - FREE_TYPES;
  return BASE_SCORE_BEYOND_FREE_TYPES + POINTS_PER_EXTRA_TYPE * extraTypes;
};

// The Sphinx itself is one of the types in the set; the scoring rule
// counts only the types *other* than the Sphinx.
const THE_SPHINX_ITSELF = 1;
const otherTypes = types.size - THE_SPHINX_ITSELF;
